actions.action:
// Economic nexus established - BPT filing required
// NH threshold: $109,000 gross business income (2025)
// Apportionment will be calculated by tables 7000-7500

// No nexus or below filing threshold - no filing required
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate NH state additions
            double additions = 0.0;

            // NH requires addback of:
            // 1. Federal interest income (U.S. government obligations)
            //    Exempt federally but taxable to NH
            // additions += revenue.federal_bond_interest;

            // 2. State income taxes deducted on federal return
            //    NH does not allow deduction of state taxes
            // additions += result.state_taxes_deducted;

            // 3. IRC provisions enacted after December 31, 2018
            //    NH uses static conformity, so post-2018 federal provisions
            //    may require addbacks (e.g., CARES Act, TCJA changes)
            // additions += result.post_2018_deductions;

            apportionment.state_additions = additions;

            // Calculate NH state subtractions
            double subtractions = 0.0;

            // NH allows subtraction of:
            // 1. NH municipal bond interest (exempt for NH purposes)
            // subtractions += revenue.nh_municipal_interest;

            // 2. Section 163(j) business interest deduction
            //    NH decoupled from federal limitation - allows full deduction
            //    of interest previously disallowed under Section 163(j)
            //    (Effective 1/1/2024 per Senate Bill 189)
            // subtractions += result.section_163j_disallowed_interest;

            // 3. Dividends received deduction (if applicable)
            // subtractions += result.nh_dividends_received_deduction;

            // 4. NH net operating loss deduction (if applicable)
            // subtractions += result.nh_nol_deduction;

            apportionment.state_subtractions = subtractions;

            // NH uses 7.5% flat rate on business profits
            apportionment.state_tax =
              apportionment.state_taxable_income * apportionment.state_tax_rate;

            // Subtract NH tax credits
            // NH offers various credits:
            // - Research & Development Credit
            // - Coos County Job Creation Credit
            // - Economic Revitalization Zone Credit
            // - Business Enterprise Tax (BET) credit against BPT
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;
